function artworkColour(letter){const c=art.crop,ctx=c.getContext('2d'),data=ctx.getImageData(0,0,c.width,c.height).data,bins=new Map(),stride=Math.max(1,Math.floor(art.w/300));let total=0;const xs=letter.points.map(p=>p[0]),ys=letter.points.map(p=>p[1]);for(let y=Math.max(0,Math.floor(Math.min(...ys)));y<Math.min(art.h,Math.max(...ys));y+=stride)for(let x=Math.max(0,Math.floor(Math.min(...xs)));x<Math.min(art.w,Math.max(...xs));x+=stride){if(art.dist[y*art.w+x]<2.5||!contains(letter.points,[x,y])||letter.holes.some(h=>contains(h,[x,y])))continue;const xx=Math.min(c.width-1,Math.floor(x/art.w*c.width)),yy=Math.min(c.height-1,Math.floor(y/art.h*c.height)),i=(yy*c.width+xx)*4;if(data[i+3]<100)continue;const rgb=[data[i],data[i+1],data[i+2]],key=rgb.map(v=>v>>5).join(',');let b=bins.get(key);if(!b){b={count:0,sum:[0,0,0]};bins.set(key,b);}b.count++;rgb.forEach((v,i)=>b.sum[i]+=v);total++;}const sorted=[...bins.values()].sort((a,b)=>b.count-a.count);if(!sorted.length)return {colour:'#a6a6a6',pattern:true};const primary=sorted[0],rgb=primary.sum.map(v=>v/primary.count);const contrasting=sorted.slice(1).filter(b=>Math.hypot(...b.sum.map((v,i)=>v/b.count-rgb[i]))>90).reduce((n,b)=>n+b.count,0);return {colour:new THREE.Color().setRGB(...rgb.map(v=>v/255),THREE.SRGBColorSpace),pattern:contrasting/total>.18};}
function artworkMaterial(base,index,face){if(state().finish!=='artwork')return base;const info=art.colors[index];if(face&&info?.pattern)return base;const mat=base.clone();mat.map=null;mat.color.copy(info?.colour instanceof THREE.Color?info.colour:new THREE.Color('#a6a6a6'));return mat;}

function addBackClamp(letter,mount,depth,unit,material){const boundary=letter.points.reduce((a,b)=>Math.hypot(a[0]-mount.point[0],a[1]-mount.point[1])<Math.hypot(b[0]-mount.point[0],b[1]-mount.point[1])?a:b),edge=pos(boundary),center=pos(mount.point),inward=center.clone().sub(edge).normalize(),angle=Math.atan2(inward.y,inward.x),u=unit*.65;const shape=new THREE.Shape();shape.moveTo(0,0);shape.lineTo(.35*u,0);shape.lineTo(.35*u,.045*u);shape.lineTo(.045*u,.045*u);shape.lineTo(.045*u,.32*u);shape.lineTo(0,.32*u);shape.closePath();const geometry=new THREE.ExtrudeGeometry(shape,{depth:.3*u,bevelEnabled:true,bevelThickness:.004*u,bevelSize:.004*u,bevelSegments:2});geometry.translate(0,0,-.15*u);geometry.rotateX(Math.PI/2);geometry.rotateZ(angle);const bracket=new THREE.Mesh(geometry,material);bracket.position.set(edge.x+inward.x*.04*u,edge.y+inward.y*.04*u,-depth);const group=new THREE.Group();group.add(bracket);const screwX=edge.x+inward.x*.23*u,screwY=edge.y+inward.y*.23*u;const shaft=new THREE.Mesh(new THREE.CylinderGeometry(.045*u,.045*u,.23*u,24),material);shaft.rotation.x=Math.PI/2;shaft.position.set(screwX,screwY,-depth-.08*u);group.add(shaft);const head=new THREE.Mesh(new THREE.SphereGeometry(.075*u,24,12),material);head.scale.z=.4;head.position.set(screwX,screwY,-depth+.06*u);group.add(head);const slot=new THREE.Mesh(new THREE.BoxGeometry(.085*u,.014*u,.01*u),new THREE.MeshStandardMaterial({color:'#454b4f',roughness:.7}));slot.position.set(screwX,screwY,-depth+.092*u);group.add(slot);const sideScrew=new THREE.Mesh(new THREE.CylinderGeometry(.038*u,.038*u,.11*u,24),material);sideScrew.quaternion.setFromUnitVectors(new THREE.Vector3(0,1,0),new THREE.Vector3(inward.x,inward.y,0));sideScrew.position.set(edge.x+inward.x*.035*u,edge.y+inward.y*.035*u,-depth+.21*u);group.add(sideScrew);addPart('clamps',group);}

